test("named snapshot CRUD stays atomic, scoped, immutable, and independent of autosave cleanup",async()=>{
  const fake=indexedDatabase();globalThis.indexedDB=fake.indexedDB;
  globalThis.localStorage={getItem:()=>null,setItem(){throw new Error("Named snapshots must never use localStorage");},removeItem(){},length:0};
  const raw=prepareWorkspaceSnapshot(payload);
  const first=await createWorkspaceSnapshot(source,"First",raw);
  assert.equal(first.nodeCount,1);assert.equal(first.edgeCount,0);assert.equal(first.raw,raw);
  first.name="Mutated return value";
  assert.equal((await readWorkspaceSnapshot(source,first.id)).name,"First");
  const renamed=await renameWorkspaceSnapshot(source,first.id,first.revision,"Renamed");
  assert.notEqual(renamed.revision,first.revision);
  const changed=prepareWorkspaceSnapshot({...payload,query:"changed"});
  const updated=await updateWorkspaceSnapshot(source,first.id,renamed.revision,changed,"Updated");
  assert.equal(updated.raw,changed);assert.equal(updated.name,"Updated");assert.equal(updated.createdAt,renamed.createdAt);
  await assert.rejects(updateWorkspaceSnapshot(source,first.id,renamed.revision,raw),/changed|conflict|stale/i);
  await assert.rejects(renameWorkspaceSnapshot(source,first.id,renamed.revision,"Lost"),/changed|conflict|stale/i);
  await assert.rejects(deleteWorkspaceSnapshot(source,first.id,renamed.revision),/changed|conflict|stale/i);
  const second=await createWorkspaceSnapshot(source,"Second",raw);
  fake.reads.length=0;
  const listed=await listWorkspaceSnapshots(source);
  assert.deepEqual(listed.map(item=>item.id),[second.id,first.id]);
  assert.ok(listed.every(item=>!("raw"in item)));
  assert.ok(fake.reads.every(([name])=>name==="snapshotMetadata"),"listing reads only the small metadata store");
  const other={...source,repositoryId:"other"};
  assert.deepEqual(await listWorkspaceSnapshots(other),[]);
  assert.equal(await readWorkspaceSnapshot(other,first.id),null);
  await assert.rejects(deleteWorkspaceSnapshot(other,first.id,updated.revision),/found/i);
  await saveWorkspaceText(raw,JSON.stringify(["repository-v2",source.basePath,`${source.serverIdentity}:old`,source.repositoryId]));
  await removeEarlierScopes(JSON.stringify(["repository-v2",source.basePath,`${source.serverIdentity}:new`,source.repositoryId]));
  assert.equal((await listWorkspaceSnapshots(source)).length,2);
  fake.failWrites=true;
  await assert.rejects(updateWorkspaceSnapshot(source,first.id,updated.revision,raw),/Quota/i);
  fake.failWrites=false;
  assert.equal((await readWorkspaceSnapshot(source,first.id)).raw,changed,"a failed write preserves the previous record");
  assert.equal((await readWorkspaceSnapshot(source,first.id)).revision,updated.revision,"failed metadata also rolls back");
  await deleteWorkspaceSnapshot(source,first.id,updated.revision);
  assert.equal(await readWorkspaceSnapshot(source,first.id),null);
  assert.equal((await listWorkspaceSnapshots(source)).length,1);
  assert.ok(fake.connections.every(db=>db.closed),"all connections close after transactions");
});

test("simultaneous stale writers cannot overwrite one another",async()=>{
  const fake=indexedDatabase();globalThis.indexedDB=fake.indexedDB;
  const raw=prepareWorkspaceSnapshot(payload),saved=await createWorkspaceSnapshot(source,"Concurrent",raw);
  const results=await Promise.allSettled([renameWorkspaceSnapshot(source,saved.id,saved.revision,"A"),renameWorkspaceSnapshot(source,saved.id,saved.revision,"B")]);
  assert.equal(results.filter(result=>result.status==="fulfilled").length,1);
  assert.equal(results.filter(result=>result.status==="rejected").length,1);
});

